import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadChhauData(){const e=readFileSync(resolve(__dirname,"../../chhau-masks-explorer/chhau-data.js"),"utf-8");return new Function(e+"\nreturn { CHHAU_INFO, PROCESS_STEPS, TRADITIONAL_MASKS, ARTISAN_COMMUNITY, GALLERY_IMAGES, REFERENCES };")()}describe("Chhau Masks Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadChhauData()}),describe("CHHAU_INFO metadata",()=>{it("contains correct Chhau Masks metadata and UNESCO status",()=>{expect(e.CHHAU_INFO.id).toBe("chhau-masks"),expect(e.CHHAU_INFO.title).toContain("Chhau Mask"),expect(e.CHHAU_INFO.originRegion).toContain("Purulia"),expect(e.CHHAU_INFO.unescoStatus).toContain("UNESCO")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.CHHAU_INFO.quickStats)).toBe(!0),expect(e.CHHAU_INFO.quickStats.length).toBe(6)})}),describe("PROCESS_STEPS & TRADITIONAL_MASKS",()=>{it("contains mask-making steps and traditional character types",()=>{expect(Array.isArray(e.PROCESS_STEPS)).toBe(!0),expect(e.PROCESS_STEPS.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.TRADITIONAL_MASKS)).toBe(!0),expect(e.TRADITIONAL_MASKS.length).toBeGreaterThanOrEqual(4)})}),describe("ARTISAN_COMMUNITY",()=>{it("contains artisan village details",()=>{expect(e.ARTISAN_COMMUNITY.title).toBeDefined(),expect(e.ARTISAN_COMMUNITY.description).toContain("Charida")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});